.re0v2-title-stage[data-family="single-focus"] .re0v2-title-char[data-accent] { font-size: 1.32em; transform: translateY(.05em); }
.re0v2-title-stage[data-family="spotlight"] .re0v2-title { margin-left: auto; justify-content: flex-end; text-align: right; }
.re0v2-title-stage[data-family="spotlight"] .re0v2-title-char:nth-child(3n + 1) { font-size: 1.18em; }
.re0v2-title-stage[data-family="spotlight"]::before { clip-path: polygon(18% 0, 100% 0, 100% 100%, 0 100%); }
.re0v2-title-stage[data-family="rhythm"] .re0v2-title { align-items: center; justify-content: space-around; gap: .02em; }
.re0v2-title-stage[data-family="rhythm"] .re0v2-title-char:nth-child(3n + 1) { font-size: 1.34em; transform: translateY(-.08em); }
.re0v2-title-stage[data-family="rhythm"] .re0v2-title-char:nth-child(3n + 2) { font-size: .68em; transform: translateY(.18em); }
.re0v2-title-stage[data-family="duet"] .re0v2-title { width: 100%; align-items: baseline; justify-content: center; gap: .08em; }
.re0v2-title-stage[data-family="duet"] .re0v2-title-char:nth-child(odd) { font-size: .78em; }
.re0v2-title-stage[data-family="duet"] .re0v2-title-char:nth-child(even) { font-size: 1.17em; }
.re0v2-title-stage[data-family="redaction"] .re0v2-title-char { padding: 0 .025em; background: linear-gradient(transparent 68%, rgba(170, 18, 42, .7) 68% 82%, transparent 82%); }
.re0v2-title-stage[data-family="redaction"] .re0v2-title-char:nth-child(2n) { transform: translateY(.12em) rotate(-2deg); }
.re0v2-title-stage[data-family="calamity"] { box-shadow: inset 0 0 76px rgba(111, 0, 20, .26); }
.re0v2-title-stage[data-family="calamity"] .re0v2-title { transform: skewX(-5deg); }
.re0v2-title-stage[data-family="calamity"] .re0v2-title-char:nth-child(2n + 1) { filter: blur(.2px); transform: translateY(calc((var(--re0v2-char-index) - 2) * 1px)); }
.re0v2-title-stage[data-family="departure"] .re0v2-title { align-items: flex-end; justify-content: flex-start; padding-left: 5%; letter-spacing: .02em; }
.re0v2-title-stage[data-family="departure"] .re0v2-title-char { transform: translateX(calc(var(--re0v2-char-index) * -.025em)); }
.re0v2-title-stage[data-family="departure"] .re0v2-title-char:last-child { margin-left: .16em; font-size: 1.45em; }

.re0v2-story-flow {
  position: relative;
  display: grid;
  gap: clamp(19px, 4cqw, 34px);
  padding: clamp(30px, 6cqw, 66px) clamp(18px, 7cqw, 76px) clamp(44px, 8cqw, 84px);
  font-family: var(--re0v2-reading-font);
  font-size: var(--re0v2-reading-size);
}
.re0v2-narration { position: relative; max-width: 42em; margin: 0 auto; color: var(--re0v2-ink); line-height: 2.05; letter-spacing: .035em; text-align: justify; overflow-wrap: anywhere; }
.re0v2-narration::first-letter { float: left; margin: .07em .18em 0 0; color: var(--re0v2-accent); font: 900 2.4em/.82 "Noto Serif SC", serif; }

.re0v2-dialogue {
  --re0v2-character-primary: var(--re0v2-accent);
  --re0v2-character-secondary: var(--re0v2-accent-2);
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr);
  gap: 14px;
  width: min(88%, 760px);
  align-items: start;
  justify-self: start;
  animation: re0v2-bubble-arrive 520ms ease both;
}
.re0v2-dialogue[data-side="player"] { grid-template-columns: minmax(0, 1fr) 70px; justify-self: end; }
.re0v2-dialogue[data-side="player"] .re0v2-avatar { grid-column: 2; }
.re0v2-dialogue[data-side="player"] .re0v2-dialogue__body { grid-column: 1; grid-row: 1; }
.re0v2-avatar {
  position: relative;
  display: grid;
  width: 66px;
  aspect-ratio: 1;
  overflow: hidden;
  place-items: center;
  border: 2px solid var(--re0v2-character-primary);
  border-radius: 10px;
  color: #fff;
  background: linear-gradient(145deg, var(--re0v2-character-primary), var(--re0v2-character-secondary));
  box-shadow: 0 8px 26px color-mix(in srgb, var(--re0v2-character-primary) 34%, transparent), inset 0 0 0 3px color-mix(in srgb, #fff 22%, transparent);
}
.re0v2-avatar::after { content: ""; position: absolute; inset: 3px; z-index: 2; pointer-events: none; border: 1px solid rgba(255, 255, 255, .5); border-radius: inherit; }
.re0v2-avatar img { position: absolute; inset: 0; z-index: 1; width: 100%; height: 100%; object-fit: cover; }
.re0v2-avatar__initial { position: relative; z-index: 0; font: 900 26px/1 "Noto Serif SC", serif; text-shadow: 0 2px 8px rgba(0, 0, 0, .4); }
[data-theme="day"] .re0v2-avatar { border-color: color-mix(in srgb, var(--re0v2-character-primary) 72%, #eaf8ff); box-shadow: 0 8px 22px rgba(36, 93, 119, .18), inset 0 0 0 3px rgba(255, 255, 255, .5); }
[data-theme="night"] .re0v2-avatar { border-radius: 8px; box-shadow: 0 0 0 2px rgba(8, 4, 12, .9), 0 0 22px color-mix(in srgb, var(--re0v2-character-primary) 45%, transparent); }
[data-theme="tea"] .re0v2-avatar { border-color: color-mix(in srgb, var(--re0v2-character-primary) 60%, #6d5a38); box-shadow: 4px 5px 0 rgba(76, 57, 30, .14), inset 0 0 0 3px rgba(255, 244, 214, .3); }

.re0v2-dialogue__body {
  position: relative;
  isolation: isolate;
  min-width: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--re0v2-character-primary) 72%, var(--re0v2-border));
  border-radius: 4px 22px 22px 22px;
  padding: 14px 17px 15px;
  color: var(--re0v2-ink);
  background: color-mix(in srgb, var(--re0v2-surface) 90%, var(--re0v2-character-primary) 10%);
  box-shadow: 0 10px 28px color-mix(in srgb, var(--re0v2-character-primary) 13%, transparent);
}
.re0v2-dialogue[data-side="player"] .re0v2-dialogue__body { border-radius: 22px 4px 22px 22px; }
.re0v2-dialogue__body::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  opacity: .23;
  background:
    repeating-linear-gradient(calc((var(--re0v2-style-seed) * 1deg) + 25deg), transparent 0 9px, var(--re0v2-character-primary) 10px, transparent 11px 22px),
    radial-gradient(circle at 88% 20%, var(--re0v2-character-secondary), transparent 26%);
}
.re0v2-dialogue[data-variant="1"] .re0v2-dialogue__body { border-radius: 20px 3px 20px 3px; border-left-width: 3px; }
.re0v2-dialogue[data-variant="2"] .re0v2-dialogue__body { border-radius: 2px; clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px)); }
.re0v2-dialogue[data-variant="3"] .re0v2-dialogue__body { border-radius: 30px 8px 30px 8px; }
.re0v2-dialogue[data-variant="4"] .re0v2-dialogue__body { border-radius: 0 26px 0 26px; border-block-width: 2px; }
.re0v2-dialogue[data-variant="5"] .re0v2-dialogue__body { border-radius: 10px 26px 10px 26px; border-right-width: 3px; }
.re0v2-dialogue[data-variant="6"] .re0v2-dialogue__body { border-radius: 3px 16px; box-shadow: 7px 7px 0 color-mix(in srgb, var(--re0v2-character-secondary) 20%, transparent); }
.re0v2-dialogue[data-variant="7"] .re0v2-dialogue__body { border-radius: 26px; border-style: double; border-width: 3px; }
.re0v2-speaker-name { display: flex; flex-wrap: wrap; align-items: baseline; gap: .02em; margin-bottom: 6px; color: var(--re0v2-ink); font: 700 13px/1.4 "Noto Sans SC", sans-serif; letter-spacing: .1em; }
.re0v2-speaker-name .is-emphasized { color: var(--re0v2-character-primary); font-size: 1.34em; font-family: "Noto Serif SC", serif; font-weight: 900; text-shadow: 0 0 16px color-mix(in srgb, var(--re0v2-character-primary) 28%, transparent); }
.re0v2-speaker-symbol { display: inline-grid; width: 1.8em; height: 1.8em; margin-left: 7px; place-items: center; border: 1px solid var(--re0v2-character-primary); border-radius: 50%; color: var(--re0v2-character-primary); font-size: .8em; letter-spacing: 0; }
.re0v2-dialogue__text { margin: 0; color: var(--re0v2-ink); font-family: var(--re0v2-reading-font); font-size: var(--re0v2-reading-size); line-height: 1.9; letter-spacing: .025em; white-space: pre-line; overflow-wrap: anywhere; }

@supports ((background-clip: text) or (-webkit-background-clip: text)) {
  .re0v2-dialogue__text {
    color: transparent;
    background: linear-gradient(90deg, var(--re0v2-ink) 0 28%, var(--re0v2-character-primary) 42%, var(--re0v2-character-secondary) 54%, var(--re0v2-ink) 70% 100%);
    background-size: 300% 100%;
    background-clip: text;
    -webkit-background-clip: text;
    animation: re0v2-text-flow 12s linear infinite;
  }
}

.re0v2-scene {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 18px;
  width: min(96%, 840px);
  min-height: 144px;
  overflow: hidden;
  align-items: center;
  justify-self: center;
  border: 1px solid var(--re0v2-border);
  padding: 21px 24px;
  background: var(--re0v2-scene-art) center / cover no-repeat, var(--re0v2-surface-2);
  box-shadow: 0 16px 34px color-mix(in srgb, var(--re0v2-accent) 13%, transparent);
}
.re0v2-scene::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(90deg, color-mix(in srgb, var(--re0v2-surface) 18%, transparent), var(--re0v2-local-panel) 36% 100%);
}
.re0v2-scene::after {
  content: "";
  position: absolute;
  inset: 10px;
  z-index: -1;
  pointer-events: none;
  border: 1px solid color-mix(in srgb, var(--re0v2-accent) 38%, transparent);
}
.re0v2-scene__compass { position: relative; display: grid; width: 54px; aspect-ratio: 1; place-items: center; border: 1px solid currentColor; transform: rotate(45deg); color: var(--re0v2-accent); background: color-mix(in srgb, var(--re0v2-surface) 72%, transparent); box-shadow: 0 0 0 6px color-mix(in srgb, var(--re0v2-accent) 12%, transparent), 0 0 24px color-mix(in srgb, var(--re0v2-accent) 30%, transparent); }
.re0v2-scene__compass::before { content: ""; position: absolute; inset: 8px; border: 1px dashed currentColor; animation: re0v2-orbit 12s linear infinite; }
.re0v2-scene__compass > span { transform: rotate(-45deg); font: 900 22px/1 "Noto Serif SC", serif; text-shadow: 0 0 14px currentColor; }
.re0v2-scene__copy { min-width: 0; border-left: 2px solid color-mix(in srgb, var(--re0v2-accent) 58%, transparent); padding: 13px 15px; background: color-mix(in srgb, var(--re0v2-local-panel) 82%, transparent); backdrop-filter: blur(5px); }
.re0v2-scene__copy p { margin: 0; }
.re0v2-scene__copy p:last-child { color: var(--re0v2-ink); line-height: 1.8; text-wrap: pretty; }
.re0v2-scene__meta { margin-bottom: 7px !important; color: var(--re0v2-accent); font: 800 10px/1.5 "Noto Sans SC", sans-serif; letter-spacing: .16em; }

[data-theme="day"] .re0v2-scene { border-radius: 22px 3px 22px 3px; background-position: center; box-shadow: 0 18px 38px rgba(41, 102, 129, .18), inset 0 0 0 5px rgba(255, 255, 255, .48); }
[data-theme="day"] .re0v2-scene::before { background: linear-gradient(90deg, rgba(236, 249, 255, .18) 0 24%, rgba(244, 252, 255, .9) 45% 100%); }
[data-theme="day"] .re0v2-scene__copy { border-radius: 2px 14px 14px 2px; background: rgba(245, 252, 255, .8); }

[data-theme="night"] .re0v2-scene { border-color: #793455; border-radius: 2px; clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 26px 100%, 0 calc(100% - 26px)); box-shadow: 9px 9px 0 rgba(79, 30, 72, .18), inset 0 0 54px rgba(0, 0, 0, .42); }
[data-theme="night"] .re0v2-scene::before { background: linear-gradient(90deg, rgba(6, 4, 10, .18) 0 22%, rgba(11, 7, 16, .86) 47% 100%); }
[data-theme="night"] .re0v2-scene__copy { border-left-color: #d04c78; background: rgba(10, 6, 15, .73); box-shadow: inset 0 0 26px rgba(128, 45, 102, .12); }

[data-theme="tea"] .re0v2-scene { border: 4px double #7f6b45; border-radius: 2px 32px 2px 32px; background-position: center; box-shadow: 0 14px 0 rgba(77, 61, 35, .08), 0 22px 38px rgba(66, 49, 25, .16); }
[data-theme="tea"] .re0v2-scene::before { background: linear-gradient(90deg, rgba(225, 210, 173, .08) 0 26%, rgba(239, 227, 199, .88) 48% 100%); }
[data-theme="tea"] .re0v2-scene::after { inset: 13px; border-style: dashed; border-radius: 0 22px 0 22px; }
[data-theme="tea"] .re0v2-scene__compass { border-radius: 50%; transform: none; background: rgba(239, 226, 195, .86); }
[data-theme="tea"] .re0v2-scene__compass > span { transform: none; }
[data-theme="tea"] .re0v2-scene__copy { border-left: 0; border-bottom: 2px solid rgba(83, 105, 62, .44); background: rgba(242, 229, 198, .79); }

.re0v2-ability {
  --re0v2-ability-accent: var(--re0v2-accent);
  --re0v2-ability-art: none;
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(170px, 30%) minmax(0, 1fr);
  gap: clamp(18px, 3cqw, 30px);
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--re0v2-ability-accent) 66%, var(--re0v2-border));
  border-radius: 8px;
  padding: clamp(16px, 2.7cqw, 24px);
  background: color-mix(in srgb, var(--re0v2-surface-2) 91%, var(--re0v2-ability-accent) 9%);
  box-shadow: inset 0 0 52px color-mix(in srgb, var(--re0v2-ability-accent) 10%, transparent), 0 18px 36px rgba(0, 0, 0, .08);
}
.re0v2-ability::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none; opacity: .1; background: var(--re0v2-theme-stage) center / cover no-repeat; mix-blend-mode: luminosity; }
.re0v2-ability[data-kind="skill"] { --re0v2-ability-accent: #4f89a7; }
.re0v2-ability[data-kind="authority"] { --re0v2-ability-accent: #8f3558; }
.re0v2-ability[data-kind="blessing"] { --re0v2-ability-accent: #c79b38; }
.re0v2-ability[data-kind="magic"] { --re0v2-ability-accent: #705ac2; }
.re0v2-ability[data-kind="spirit"] { --re0v2-ability-accent: #3fa8b0; }
.re0v2-ability[data-kind="racial"] { --re0v2-ability-accent: #b5503e; }
.re0v2-ability[data-kind="martial"] { --re0v2-ability-accent: #557284; }
.re0v2-ability__sigil { position: relative; display: grid; min-height: 176px; overflow: hidden; place-items: end start; border: 1px solid color-mix(in srgb, var(--re0v2-ability-accent) 76%, #fff 12%); border-radius: 6px; padding: 12px; color: #fff; background: linear-gradient(180deg, transparent 28%, rgba(0, 0, 0, .78)), var(--re0v2-ability-art) center / cover no-repeat, #111; box-shadow: inset 0 0 36px rgba(0, 0, 0, .28), 0 10px 24px color-mix(in srgb, var(--re0v2-ability-accent) 18%, transparent); font: 700 20px/1 "Noto Serif SC", serif; }
.re0v2-ability__sigil::before,
.re0v2-ability__sigil::after { content: ""; position: absolute; inset: 12px; border: 1px solid color-mix(in srgb, var(--re0v2-ability-accent) 68%, #fff 18%); border-radius: 50%; opacity: .56; }
.re0v2-ability__sigil::after { inset: 28px; border-style: dashed; animation: re0v2-orbit 9s linear infinite; }
.re0v2-ability__sigil > span { position: relative; z-index: 2; display: grid; width: 36px; aspect-ratio: 1; place-items: center; border: 1px solid color-mix(in srgb, var(--re0v2-ability-accent) 70%, #fff); border-radius: 4px; color: #fff; background: rgba(5, 5, 8, .64); text-shadow: 0 0 18px var(--re0v2-ability-accent); backdrop-filter: blur(4px); }
.re0v2-ability__body { position: relative; z-index: 1; min-width: 0; align-self: center; }
.re0v2-ability__body h2 { margin: 2px 0 5px; color: var(--re0v2-ink); font: 900 clamp(22px, 4cqw, 34px)/1.25 "Noto Serif SC", serif; letter-spacing: .06em; }
.re0v2-ability__eyebrow,
.re0v2-ability__affinity { margin: 0; color: var(--re0v2-ability-accent); font: 700 9px/1.6 "Noto Sans SC", sans-serif; letter-spacing: .16em; }
.re0v2-ability__effect { margin: 12px 0; color: var(--re0v2-ink); font-size: var(--re0v2-reading-size); line-height: 1.85; }
.re0v2-ability__description { border-top: 1px solid color-mix(in srgb, var(--re0v2-ability-accent) 40%, transparent); padding-top: 9px; color: var(--re0v2-muted); font-size: .86em; }
.re0v2-ability__description summary { width: max-content; color: var(--re0v2-ability-accent); font: 700 11px "Noto Sans SC", sans-serif; cursor: pointer; }
.re0v2-ability__description p { margin: 8px 0 0; line-height: 1.75; }

[data-theme="day"] .re0v2-ability { border-radius: 24px 4px 24px 4px; background: linear-gradient(110deg, rgba(236, 248, 253, .92), rgba(255, 255, 255, .95) 54%, rgba(227, 241, 247, .88)); box-shadow: 0 18px 40px rgba(38, 88, 110, .13), inset 0 0 0 5px rgba(255, 255, 255, .5); }
[data-theme="day"] .re0v2-ability__sigil { border-radius: 16px 2px 16px 2px; clip-path: polygon(0 0, 92% 0, 100% 12%, 100% 100%, 0 100%); }

[data-theme="night"] .re0v2-ability { border-radius: 2px; clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px)); background: linear-gradient(115deg, rgba(20, 10, 25, .98), rgba(28, 17, 34, .94) 56%, rgba(11, 7, 16, .98)); box-shadow: 8px 8px 0 color-mix(in srgb, var(--re0v2-ability-accent) 12%, transparent), inset 0 0 56px rgba(0, 0, 0, .46); }
[data-theme="night"] .re0v2-ability::before { opacity: .18; mix-blend-mode: screen; }
[data-theme="night"] .re0v2-ability__sigil { border-radius: 0; }

[data-theme="tea"] .re0v2-ability { border: 4px double color-mix(in srgb, var(--re0v2-ability-accent) 66%, #7c6844); border-radius: 3px 28px 3px 28px; background: linear-gradient(96deg, rgba(221, 205, 167, .92), rgba(244, 232, 202, .96) 47%, rgba(232, 217, 181, .94)); box-shadow: 0 12px 0 rgba(73, 54, 28, .07), 0 20px 34px rgba(65, 48, 23, .13); }
[data-theme="tea"] .re0v2-ability::before { opacity: .13; mix-blend-mode: multiply; }
[data-theme="tea"] .re0v2-ability__sigil { border-radius: 50% 50% 6px 6px / 18% 18% 6px 6px; filter: saturate(.82) sepia(.08); }

.re0v2-ability[data-effect="steel-scan"]::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, transparent 0 45%, color-mix(in srgb, var(--re0v2-ability-accent) 40%, transparent) 49%, transparent 53%); transform: translateY(-100%); animation: re0v2-scan 5s ease-in-out infinite; }
.re0v2-ability[data-effect="broken-ring"] .re0v2-ability__sigil::before { border: 0; background: conic-gradient(currentColor 0 18%, transparent 18% 29%, currentColor 29% 56%, transparent 56% 72%, currentColor 72% 92%, transparent 92%); mask: radial-gradient(circle, transparent 55%, #000 57%); animation: re0v2-broken-spin 8s steps(12) infinite; }
.re0v2-ability[data-effect="blessing-halo"] .re0v2-ability__sigil { filter: drop-shadow(0 0 13px color-mix(in srgb, var(--re0v2-ability-accent) 62%, transparent)); }
.re0v2-ability[data-effect="blessing-halo"] .re0v2-ability__sigil::before { border: 0; background: repeating-conic-gradient(from 0deg, currentColor 0 2deg, transparent 2deg 14deg); mask: radial-gradient(circle, transparent 57%, #000 58%); animation: re0v2-orbit 18s linear infinite reverse; }
.re0v2-ability[data-effect="arcane-orbit"] .re0v2-ability__sigil::before { border-style: double; border-width: 4px; clip-path: polygon(50% 0, 61% 35%, 100% 50%, 61% 65%, 50% 100%, 39% 65%, 0 50%, 39% 35%); animation: re0v2-orbit 11s linear infinite; }
.re0v2-ability[data-effect="spirit-motes"] .re0v2-ability__sigil { background-image: radial-gradient(circle at 20% 30%, currentColor 0 2px, transparent 3px), radial-gradient(circle at 78% 28%, currentColor 0 3px, transparent 4px), radial-gradient(circle at 67% 78%, currentColor 0 2px, transparent 3px), radial-gradient(circle at 28% 72%, currentColor 0 2px, transparent 3px); animation: re0v2-motes 4s ease-in-out infinite; }
.re0v2-ability[data-effect="bloodline-pulse"] .re0v2-ability__sigil::before { border-radius: 0; clip-path: polygon(50% 0, 62% 36%, 100% 50%, 62% 64%, 50% 100%, 38% 64%, 0 50%, 38% 36%); background: color-mix(in srgb, currentColor 20%, transparent); animation: re0v2-pulse 2.2s ease-in-out infinite; }
.re0v2-ability[data-effect="martial-slash"] .re0v2-ability__sigil::before,
